def assign_unclassified_stages(apps, schema_editor):
    """Give every legacy unclassified class an explicit tenant-owned stage.

    No stage is inferred from a class name or display order.  The neutral stage
    exists only to make the Phase 3 exactly-one-stage invariant safe for legacy
    rows; administrators can subsequently assign the intended stage.
    """
    AcademicStage = apps.get_model('students', 'AcademicStage')
    SchoolClass = apps.get_model('students', 'SchoolClass')
    db_alias = schema_editor.connection.alias

    school_ids = SchoolClass.objects.using(db_alias).filter(
        academic_stage__isnull=True
    ).values_list('school_id', flat=True).distinct()
    for school_id in school_ids:
        stage = next(
            (
                candidate
                for candidate in AcademicStage.objects.using(db_alias).filter(
                    school_id=school_id
                )
                if ' '.join((candidate.name or '').split()).casefold() == 'unclassified'
            ),
            None,
        )
        if stage is None:
            stage = AcademicStage.objects.using(db_alias).create(
                school_id=school_id,
                name='Unclassified',
                display_order=9999,
                is_active=False,
            )
        SchoolClass.objects.using(db_alias).filter(
            school_id=school_id,
            academic_stage__isnull=True,
        ).update(academic_stage_id=stage.pk)


